func schema_pkg_apis_ome_v1beta1_CoordinationPacing(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "CoordinationPacing controls how surge / drain pacing is computed within a coordination group.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"type": {
						SchemaProps: spec.SchemaProps{
							Description: "Type selects the pacing computation.\n  - PerComponent: each Component's lifecycle.updateStrategy\n    rollingUpdate applies independently. Group-wide MaxSurge\n    still applies on top. Default.\n  - RatioBalanced: pacing surges proportionally across all\n    Components in the group, never letting the cross-Component\n    ratio drift past the original.",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"maxSurge": {
						SchemaProps: spec.SchemaProps{
							Description: "MaxSurge is the maximum fraction (or absolute count) of pods OMENative may add above the desired Component replica count during a coordinated rollout. Applies group-wide. Default: 25%.",
							Ref:         ref("k8s.io/apimachinery/pkg/util/intstr.IntOrString"),
						},
					},
					"maxUnavailable": {
						SchemaProps: spec.SchemaProps{
							Description: "MaxUnavailable is the maximum fraction (or absolute count) of pods that may be not-Ready at once during the rollout. Applies group-wide. Default: 0.",
							Ref:         ref("k8s.io/apimachinery/pkg/util/intstr.IntOrString"),
						},
					},
					"ratioTolerancePercent": {
						SchemaProps: spec.SchemaProps{
							Description: "RatioTolerancePercent bounds how far the components in a RatioBalanced group may drift from their starting proportion during a roll. The ratio is taken larger-pool : smaller-pool, so it is direction-independent — prefill:decode and decode:prefill are the same constraint — and is anchored to the counts observed when the roll began. A surge OR drain is paused whenever a step would push any component pair's live serving proportion outside starting_ratio ± this percent, and resumes once the pools rebalance. Example: a group that starts 2:1 with a value of 5 holds the live proportion between 1.9:1 and 2.1:1. For three or more components every pair is checked. When nil, the operator-configured default (the coordination block of the operator's ConfigMap) applies at resolution; unresolved (nil after resolution) means no drift bound is enforced.",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
				},
			},
		},
		Dependencies: []string{
			"k8s.io/apimachinery/pkg/util/intstr.IntOrString"},
	}
}

